function.arguments:
{"path":"rapor.ps1","content":"Get-ChildItem -Path .\loglar -Recurse -File -Filter "*.log" | ForEach-Object {
    $logFile = $_.FullName
    $relativePath = $logFile.Substring((Resolve-Path .\loglar).Path.Length + 1)

    # ERROR, WARN ve INFO satırlarını say
    $errorCount = (Select-String -Path $logFile -Pattern "^.*?ERROR.*$" | Measure-Object).Count
    $warnCount = (Select-String -Path $logFile -Pattern "^.*?WARN.*$" | Measure-Object).Count
    $infoCount = (Select-String -Path $logFile -Pattern "^.*?INFO.*$" | Measure-Object).Count

    # CSV satırını oluştur ve yaz
    Write-Output "$relativePath,$errorCount,$warnCount,$infoCount"
}"}
